/**
 * The stat blocks an attack load declares. GENERATED — do not edit by hand.
 *
 * Copied verbatim from the server's own tables,
 * `server/src/game-data/stats/monsterStats.ts` (`props`) and
 * `server/src/game-data/stats/championStats.ts` (`t`, `props`), by a one-off
 * Bun script that imports those files and re-emits them; the monster half is
 * re-emitted by `npm run gen:attack-stats` (`tools/gen-attack-stats.mjs`)
 * whenever `monsterStats.ts` changes.
 *
 * Why a second copy exists beside `web/src/game/combat/rules/combatStatsData.ts`:
 * the attack gate compares *every* key of the server's `props` block against
 * what the client sends, to two decimal places
 * (`server/src/services/maproom/validateAttack.ts:44-90`), and a mismatch
 * bans the account. The shared combat table deliberately strips the economy
 * ladders (`cTime`, `cResource`, `hTime`, `hResource`, the champion feeding
 * and render-offset keys) because the battle never reads them — so it cannot
 * be what `attackData` carries. This table is the Flash client's
 * `CREATURELOCKER._creatures[id].props` and `CHAMPIONCAGE._guardians[id].props`
 * (`client/scripts/ATTACK.as:199-222`), and nothing but the attack load reads it.
 */

/** A prop ladder: one entry per level, numbers or (for a champion) strings. */
export type StatLadder = readonly number[] | readonly string[];

